import{_ as a,o,c as r,a2 as e}from"./chunks/framework.C4u7U0Dw.js";const c=JSON.parse('{"title":"第 7 章 计划模式与长任务执行（易懂版）","description":"","frontmatter":{},"headers":[],"relativePath":"easy/第7章 计划模式与长任务执行（易懂版）.md","filePath":"easy/第7章 计划模式与长任务执行（易懂版）.md"}'),s={name:"easy/第7章 计划模式与长任务执行（易懂版）.md"};function n(l,t,i,h,d,u){return o(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="第-7-章-计划模式与长任务执行-易懂版" tabindex="-1">第 7 章 计划模式与长任务执行（易懂版） <a class="header-anchor" href="#第-7-章-计划模式与长任务执行-易懂版" aria-label="Permalink to &quot;第 7 章 计划模式与长任务执行（易懂版）&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">📖 想读完整版？</p><p>这页是<strong>易懂版</strong>，用大白话讲重点。想系统学习，请读 [第 7 章 计划模式与长任务执行（完整版）](../../bluebook/第一篇 使用手册：先把我用起来/第 7 章 计划模式与长任务执行.md)。</p></div><h2 id="这章讲什么-一句话" tabindex="-1">这章讲什么（一句话） <a class="header-anchor" href="#这章讲什么-一句话" aria-label="Permalink to &quot;这章讲什么（一句话）&quot;">​</a></h2><p><strong>任务太大？别怕——我会先写计划给你看，你点头了我再一步步干。</strong></p><h2 id="先打个比方" tabindex="-1">先打个比方 <a class="header-anchor" href="#先打个比方" aria-label="Permalink to &quot;先打个比方&quot;">​</a></h2><p>装修房子前，好师傅先给你看<strong>施工方案</strong>：拆哪堵墙、铺什么地板、分几步、多久完工。你确认了才动工。</p><p>计划模式就是&quot;装修先出方案&quot;——<strong>大任务先出计划，你审批，我执行。</strong></p><h2 id="核心就-3-件事" tabindex="-1">核心就 3 件事 <a class="header-anchor" href="#核心就-3-件事" aria-label="Permalink to &quot;核心就 3 件事&quot;">​</a></h2><ol><li><strong>先计划后动手</strong>：遇到大任务，我先产出&quot;分几步、每步做什么&quot;的计划，<strong>给你看，等你确认</strong>。</li><li><strong>按步骤走，随时汇报</strong>：开工后一步步推进，每完成一步都让你知道进展。</li><li><strong>进度可查</strong>：你可以随时看进行到哪了，喊停、改方向都行。</li></ol><h2 id="什么时候该用计划模式" tabindex="-1">什么时候该用计划模式？ <a class="header-anchor" href="#什么时候该用计划模式" aria-label="Permalink to &quot;什么时候该用计划模式？&quot;">​</a></h2><ul><li>✅ 任务要动<strong>很多文件</strong>；</li><li>✅ 任务分<strong>多个阶段</strong>（调研→方案→实施→验收）；</li><li>✅ 任务<strong>干错代价大</strong>（删除、覆盖、上线）；</li><li>✅ 任务需要<strong>多个工具配合</strong>。</li></ul><h2 id="上手小例子" tabindex="-1">上手小例子 <a class="header-anchor" href="#上手小例子" aria-label="Permalink to &quot;上手小例子&quot;">​</a></h2><blockquote><p><strong>指令</strong>：&quot;帮我整理这个项目：先分析现状，再写改进方案，最后实施。&quot;</p><p><strong>你会看到</strong>：我<strong>先交一份计划</strong>——① 读文件分析 → ② 写方案给你看 → ③ 你确认后实施 → ④ 交付。你确认了，我才开干。</p></blockquote><h2 id="别踩的坑" tabindex="-1">别踩的坑 <a class="header-anchor" href="#别踩的坑" aria-label="Permalink to &quot;别踩的坑&quot;">​</a></h2><ul><li>❌ 计划没确认就开跑——<strong>没批准就动工 = 白干风险</strong>；</li><li>❌ 中途跑偏不吭声——发现方向不对，<strong>随时说</strong>，我会调整；</li><li>❌ 大任务当成一步做完——<strong>没计划的大任务，基本都会翻车</strong>。</li></ul><h2 id="一句话总结" tabindex="-1">一句话总结 <a class="header-anchor" href="#一句话总结" aria-label="Permalink to &quot;一句话总结&quot;">​</a></h2><p><strong>大任务 = 先给计划 → 你审批 → 分步执行 → 随时汇报。</strong></p><h2 id="一分钟测试" tabindex="-1">一分钟测试 <a class="header-anchor" href="#一分钟测试" aria-label="Permalink to &quot;一分钟测试&quot;">​</a></h2><p>下一个大任务来临时，先问：<strong>&quot;这个任务需要先看计划吗？&quot;</strong> 需要的话，就说一句&quot;先给我个计划&quot;。</p><p>👉 [下一章：AI 团队，一句话召唤多智能体协作（易懂版）](第8章 AI 团队：一句话召唤多智能体协作（易懂版）.md)</p>',20)])])}const _=a(s,[["render",n]]);export{c as __pageData,_ as default};
